    desc: "แผ่นปะแบบเย็นกับแผ่นปะวัลคาไนซ์แบบร้อนสำหรับการซ่อมยาง: แต่ละแบบทำงานอย่างไร ควรใช้แบบไหน และอู่ต้องมีสต็อกอะไรสำหรับทั้งสองแบบ",
