            <tr><td>กาวอยู่ แต่ตัวน้ำหนักลอก</td><td>การเคลือบขอบล้อพรุน เต็มฝุ่น หรือคิวไม่ดี</td><td>ทดสอบบนแม็กซ์เปลือย ทำความสะอาดและขัดเบาๆ กับการเคลือบที่มีปัญหา</td></tr>
