            <tr><td>CTR-FE-02A</td><td>Fe (เหล็ก)</td><td>12 x 5 กรัม</td><td>140 x 19 x 3.8 มม.</td><td>กลม / มุมฉาก</td><td>100 / 50 ชิ้น</td></tr>
