            <tr><td>CTR-PB-02A</td><td>Pb (ตะกั่ว)</td><td>12 x 5 กรัม</td><td>105 x 18 x 4 มม.</td><td>กลม / มุมฉาก</td><td>100 / 50 ชิ้น</td></tr>
