      <p>ไม่ใช่ทุกรอยรั่วต้องใช้การซ่อมแบบเดียวกัน และการเลือกวิธีผิดสามารถเปลี่ยนยางที่ปลอดภัยเป็นยางที่อันตรายได้ จุ๊บอุดอาจพาผู้ขับกลับบ้านได้ แต่มีเพียงแผ่นปะภายในเท่านั้นที่ฟื้นฟูยางกลับสู่สภาพถาวรที่พร้อมใช้บนถนน คู่มือนี้อธิบายสามตัวเลือกหลัก - จุ๊บอุด (ด้ายอุด) แผ่นปะยาง และปะรูเห็ด - และวิธีเก็บและเลือก</p>

